// golf by @FabriceNeyret2 thanks
void mainImage(out vec4 O, vec2 U)
{
        //U = floor(U/8.)*8.;
        vec2 R = iResolution.xy,
             u = 130.*(U+U - R) / R.y;

        float i;
        for(O *= i; i < 1.; i += 1./ceil(iTime) )
                O += cos( dot(  u , cos(6.28*i+vec2(0,11)) ));// +  sin(u.x*u.y)/15.;
        //O = .5 + O/fwidth(O);       
        O = .5 + .25*O/sqrt(ceil(iTime));
}

